-- ============================================
-- LUMA — Thème 15 : LONG 1/3 x4 — Un séjour complet d'une semaine avec plusieurs journées thématiques
-- ============================================


update scenarios set content = '{"characters": {"alice": "Alice", "announcement": "annonce", "you_thought": "narration"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alice", "text": "We made it! A whole week in London ahead of us. Where do we even start?", "text_fr": "On y est arrivés ! Toute une semaine à Londres devant nous. On commence par où ?", "choices": [{"text": "Let''s ease in with a walking tour of the city center today.", "text_fr": "Commençons doucement avec une visite à pied du centre-ville aujourd''hui.", "next": "n2"}, {"text": "I say we dive right into the major landmarks immediately!", "text_fr": "Je dis qu''on plonge directement dans les monuments majeurs immédiatement !", "next": "n2b"}]}, "n2": {"speaker": "alice", "text": "Good call, easing in after the flight makes sense.", "text_fr": "Bonne idée, y aller doucement après le vol a du sens.", "choices": [{"text": "Exactly, let''s just wander and get a feel for the city.", "text_fr": "Exactement, baladons-nous juste et prenons le pouls de la ville.", "next": "n3"}]}, "n2b": {"speaker": "alice", "text": "Ha, love the energy! Let''s channel that into today then.", "text_fr": "Ha, j''adore l''énergie ! Canalisons ça pour aujourd''hui alors.", "choices": [{"text": "Let''s start with Buckingham Palace and go from there.", "text_fr": "Commençons par Buckingham Palace et on continue à partir de là.", "next": "n3"}]}, "n3": {"speaker": "alice", "text": "(Day 2) Museum day today, right? I''ve been looking forward to this.", "text_fr": "(Jour 2) Journée musée aujourd''hui, non ? J''attendais ça avec impatience.", "choices": [{"text": "Absolutely, the British Museum first, then maybe the Natural History Museum.", "text_fr": "Absolument, le British Museum d''abord, puis peut-être le Musée d''Histoire Naturelle.", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(Hours pass exploring exhibits, both of you completely absorbed in history.)", "text_fr": "(Des heures passent à explorer les expositions, tous les deux complètement absorbés par l''histoire.)", "choices": [{"text": "(Reflect on how much you''re learning today.)", "text_fr": "(Réfléchis à combien tu apprends aujourd''hui.)", "next": "n5"}]}, "n5": {"speaker": "alice", "text": "This has honestly exceeded my expectations. I could spend days just in this museum.", "text_fr": "Ça a honnêtement dépassé mes attentes. Je pourrais passer des jours juste dans ce musée.", "choices": [{"text": "Same here, though we should save some energy for the rest of the week!", "text_fr": "Pareil pour moi, même si on devrait garder de l''énergie pour le reste de la semaine !", "next": "n6"}]}, "n6": {"speaker": "announcement", "text": "(Day 3, news alert) Tube strike announced for today, affecting most Underground lines.", "text_fr": "(Jour 3, alerte info) Grève du métro annoncée pour aujourd''hui, affectant la plupart des lignes du métro.", "choices": [{"text": "Well, that changes our plans. Let''s figure out alternate transport.", "text_fr": "Bon, ça change nos plans. Trouvons un transport alternatif.", "next": "n7"}, {"text": "Let''s just walk everywhere today, turn it into an adventure.", "text_fr": "Marchons partout aujourd''hui, transformons ça en aventure.", "next": "n7b"}]}, "n7": {"speaker": "alice", "text": "Buses should still run, or we could try walking to nearby spots.", "text_fr": "Les bus devraient toujours rouler, ou on pourrait essayer de marcher vers des endroits proches.", "choices": [{"text": "Let''s check the bus routes and adjust today''s itinerary.", "text_fr": "Vérifions les itinéraires de bus et ajustons l''itinéraire d''aujourd''hui.", "next": "n8"}]}, "n7b": {"speaker": "alice", "text": "Ha, I love that attitude! London''s actually great for walking anyway.", "text_fr": "Ha, j''adore cette attitude ! Londres est en fait super pour marcher de toute façon.", "choices": [{"text": "Exactly, let''s discover some hidden streets along the way.", "text_fr": "Exactement, découvrons des rues cachées en chemin.", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(Despite the strike, you discover charming neighborhoods you''d have otherwise missed.)", "text_fr": "(Malgré la grève, vous découvrez des quartiers charmants que vous auriez autrement manqués.)", "choices": [{"text": "Honestly, this strike accidentally gave us one of our best days.", "text_fr": "Honnêtement, cette grève nous a accidentellement donné l''une de nos meilleures journées.", "next": "n9"}]}, "n9": {"speaker": "alice", "text": "(Day 5) After all that walking, how about a relaxing day? Maybe a park picnic?", "text_fr": "(Jour 5) Après toute cette marche, et si on avait une journée relaxante ? Peut-être un pique-nique au parc ?", "choices": [{"text": "That sounds perfect, Hyde Park would be lovely for that.", "text_fr": "Ça a l''air parfait, Hyde Park serait adorable pour ça.", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(A peaceful afternoon in the park recharges you both for the final days ahead.)", "text_fr": "(Un après-midi paisible au parc vous recharge tous les deux pour les derniers jours à venir.)", "choices": [{"text": "(Feel grateful for this slower, restorative day.)", "text_fr": "(Ressens de la gratitude pour cette journée plus lente et ressourçante.)", "next": "n11"}]}, "n11": {"speaker": "alice", "text": "(Final day) Hard to believe it''s already our last day here.", "text_fr": "(Dernier jour) Difficile de croire que c''est déjà notre dernier jour ici.", "choices": [{"text": "I know, this week went by so fast. Let''s make today count.", "text_fr": "Je sais, cette semaine est passée si vite. Faisons que cette journée compte.", "next": "n12"}, {"text": "Let''s revisit our favorite spot from the whole week before we leave.", "text_fr": "Retournons voir notre endroit préféré de toute la semaine avant de partir.", "next": "n12"}]}, "n12": {"speaker": "you_thought", "text": "(You spend your final hours soaking in the city, grateful for the whole journey.)", "text_fr": "(Vous passez vos dernières heures à vous imprégner de la ville, reconnaissants pour tout le voyage.)", "choices": [{"text": "(Take one last look at the skyline before heading to the airport.)", "text_fr": "(Jette un dernier regard à l''horizon avant de partir pour l''aéroport.)", "next": "n13"}]}, "n13": {"speaker": "alice", "text": "What a week — museums, strikes, parks, pubs. It really had everything.", "text_fr": "Quelle semaine — musées, grèves, parcs, pubs. Elle a vraiment eu de tout.", "choices": [{"text": "It really did. This might be one of the best trips I''ve ever taken.", "text_fr": "C''est vraiment le cas. Ça pourrait bien être l''un des meilleurs voyages que j''aie faits.", "next": "end_week"}]}, "end_week": {"speaker": "alice", "text": "Agreed completely. Here''s to London, and to many more adventures together.", "text_fr": "Complètement d''accord. À Londres, et à beaucoup plus d''aventures ensemble.", "end": true, "ending_label": "Une semaine complète à Londres, riche en tout 🇬🇧📅✨"}}}'::jsonb, is_playable = true
where title = 'Un séjour complet d''''une semaine avec plusieurs journées thématiques'
  and theme_id = (select id from scenario_themes where position = 15 and language_id = (select id from languages where code = 'en'));
